_DIAG_RULES_C = [(rid, title, cat, lvl, re.compile(rx, re.I), advice) for rid, title, cat, lvl, rx, advice in DIAG_RULES]
_LEVEL_ORDER = {"crit": 0, "warn": 1, "info": 2}
_LEVEL_LABEL = {"crit": "CRITICAL", "warn": "WARNING", "info": "INFO"}


def _diag_clock_now(clock_text, fallback=None):
    """The switch's own 'now' from 'show clock' (so a look-back window is measured on the switch's clock)."""
    m = _LOG_CLOCK_RE.search(clock_text or "")
    if m:
        try:
            return datetime(int(m.group(6)), _LOG_MONTHS[m.group(4)[:3].title()], int(m.group(5)),
                                     int(m.group(1)), int(m.group(2)), int(m.group(3)))
        except (KeyError, ValueError):
            pass
    return fallback or datetime.now()


def _diag_parse_ts(line, now):
    """(datetime or None, flag) of a log line. flag '*' = clock not synchronized, '.' = synchronized but not by NTP."""
    m = _LOG_TS_RE.match(line)
    if not m:
        return None, ""
    mon = _LOG_MONTHS.get(m.group("mon"))
    if not mon:
        return None, ""
    year = int(m.group("year")) if m.group("year") else now.year
    try:
        ts = datetime(year, mon, int(m.group("day")), int(m.group("h")), int(m.group("m")), int(m.group("s")))
    except ValueError:
        return None, m.group("flag") or ""
    if not m.group("year") and ts > now + timedelta(days=1):
        try:
            ts = ts.replace(year=year - 1)
        except ValueError:
            return None, m.group("flag") or ""
    return ts, m.group("flag") or ""


_LOG_UPT_RE = re.compile(r"^\s*(?:\d+:\s*)?(?:(?P<hh>\d+):(?P<mm>\d{2}):(?P<ss>\d{2})(?:\.\d+)?|(?P<y>\d+)y(?P<w2>\d+)w|"
                         r"(?P<w>\d+)w(?P<d>\d+)d|(?P<d2>\d+)d(?P<h>\d{2})h):")


def _diag_parse_uptime_ts(line, boot):
    """Log lines stamped with the switch uptime ('service timestamps log uptime') -> the date they were logged, via the boot time."""
    m = _LOG_UPT_RE.match(line)
    if not m or boot is None:
        return None
    g = m.groupdict()
    if g["hh"] is not None:
        secs = int(g["hh"]) * 3600 + int(g["mm"]) * 60 + int(g["ss"])
    elif g["y"] is not None:
        secs = int(g["y"]) * 365 * 86400 + int(g["w2"]) * 7 * 86400
    elif g["w"] is not None:
        secs = int(g["w"]) * 7 * 86400 + int(g["d"]) * 86400
    else:
        secs = int(g["d2"]) * 86400 + int(g["h"]) * 3600
    return boot + timedelta(seconds=secs)


def _diag_log_now(now, cfg_text):
    """(now on the clock the LOG lines use, note). Syslog lines are stamped in UTC unless 'service timestamps log ... localtime'
    is configured, while 'show clock' shows the configured 'clock timezone' - so the two can differ by the zone offset."""
    text = cfg_text or ""
    m = re.search(r"(?im)^clock timezone\s+\S+\s+(-?\d+)(?:\s+(\d+))?", text)
    if not m:
        return now, ""
    off = (-1 if m.group(1).startswith("-") else 1) * (abs(int(m.group(1))) * 60 + int(m.group(2) or 0))
    st = re.search(r"(?im)^service timestamps log\b.*$", text)
    if off == 0 or (st and re.search(r"\blocaltime\b", st.group(0), re.I)):
        return now, ""
    sign = "+" if off > 0 else "-"
    return now - timedelta(minutes=off), (f"The log lines are stamped in UTC but 'show clock' shows local time (UTC{sign}{abs(off) // 60}:{abs(off) % 60:02d}); "
                                          "the look-back window was converted to the clock the log uses.")


def _diag_clock_facts(clock_text):
    """(the 'show clock' line as the switch printed it, the time source line) - both '' when not present."""
    line = next((l.strip() for l in (clock_text or "").splitlines() if _LOG_CLOCK_RE.search(l)), "")
    src = re.search(r"(?im)^\s*Time source is\s+(.+?)\s*$", clock_text or "")
    return line, (src.group(1) if src else "")


def _diag_short(line, width=230):
    line = " ".join(str(line).split())
    return line if len(line) <= width else line[:width - 3] + "..."


def _diag_uptime_minutes(text):
    m = re.search(r"(?im)\buptime is (.+)$", text or "")
    if not m:
        return None
    total = 0
    for n, unit in re.findall(r"(\d+)\s+(year|week|day|hour|minute)s?", m.group(1)):
        total += int(n) * {"year": 525600, "week": 10080, "day": 1440, "hour": 60, "minute": 1}[unit]
    return total


def parse_show_switch(text):
    """[{switch, role, state}] from 'show switch', or None when the switch is not a stack / the command is not valid."""
    if not text or re.search(r"(?im)^\s*%\s*(invalid|ambiguous|incomplete)", text) or "Invalid input" in text:
        return None
    rows = []
    for line in text.splitlines():
        m = re.match(r"^\s*\*?\s*(\d+)\s+(\w+)\s+[0-9a-f]{4}\.[0-9a-f]{4}\.[0-9a-f]{4}\s+\d+\s+\S+\s+(.+?)\s*$", line, re.I)
        if m:
            rows.append({"switch": int(m.group(1)), "role": m.group(2), "state": m.group(3)})
    return rows or None


_AUTH_ROW_RE = re.compile(r"^\s*([A-Za-z][A-Za-z-]*\d[\w/.:-]*)\s+([0-9a-f]{4}\.[0-9a-f]{4}\.[0-9a-f]{4})\s+(\S+)\s+(\S+)\s+(.+?)\s+([0-9A-Fa-f]{16,})\s*$", re.I)
_AUTH_OK_STATES = ("auth", "authz success", "auth success", "authc success")


def parse_auth_sessions(text):
    """[{port, mac, method, domain, status, ok}] from 'show authentication sessions' (802.1X / MAB / web-auth),
    or None when the command is not available on this switch. An empty list means no sessions exist."""
    if not text or re.search(r"(?im)^\s*%\s*(invalid|ambiguous|incomplete)", text) or "Invalid input" in text:
        return None
    rows = []
    for line in text.splitlines():
        m = _AUTH_ROW_RE.match(line)
        if m:
            status = " ".join(m.group(5).split())
            rows.append({"port": m.group(1), "mac": m.group(2).lower(), "method": m.group(3).lower(), "domain": m.group(4).upper(),
                         "status": status, "ok": status.lower() in _AUTH_OK_STATES})
    return rows


def analyze_switch_logs(sections, lookback_hours=0, label="", host=""):
    """Rule-based analysis of the output of DIAG_LOG_COMMANDS ({command: output}). Pure function, no network.
    Returns a JSON-friendly dict: verdict (green/amber/red), findings, top messages, facts, notes."""
    log_text = sections.get("show logging", "") or ""
    clock_text = sections.get("show clock detail") or sections.get("show clock") or ""
    version_text = sections.get("show version", "") or ""
    # The look-back window is measured on the SWITCH's own clock ('show clock'), never on this computer's clock - a switch
    # whose clock is wrong (NTP problem) still has log lines stamped by that same clock, so the two stay consistent.
    clock_ok = bool(_LOG_CLOCK_RE.search(clock_text))
    switch_now = _diag_clock_now(clock_text)
    now, tz_note = _diag_log_now(switch_now, sections.get(DIAG_CLOCK_CFG_CMD, ""))
    mins_up = _diag_uptime_minutes(version_text)
    boot = now - timedelta(minutes=mins_up) if mins_up is not None else None
    cutoff = now - timedelta(hours=lookback_hours) if lookback_hours else None
    notes = []
    if lookback_hours and not clock_ok:
        notes.append("'show clock' could not be read from this switch, so this computer's clock was used for the look-back window.")
    if lookback_hours and tz_note:
        notes.append(tz_note)

    # ---- the log buffer ----
    entries, outside, ts_seen, star_seen, presync = [], 0, 0, 0, 0
    for line in log_text.splitlines():
        msg = _LOG_MSG_RE.search(line)
        trace = (not msg) and _LOG_TRACE_RE.search(line)
        if not msg and not trace:
            continue
        ts, flag = _diag_parse_ts(line, now)
        if ts is None:
            ts = _diag_parse_uptime_ts(line, boot)               # 'service timestamps log uptime' lines
        bogus = False
        if ts:
            ts_seen += 1
            if flag == "*":
                star_seen += 1
            if cutoff:
                inside = ts >= cutoff
                if flag == "*" and boot is not None and ts < boot - timedelta(days=1):
                    # logged before the clock was set (the boot-time default date): it happened right after the boot
                    bogus, inside = True, boot >= cutoff
                    presync += 1
                if not inside:
                    outside += 1
                    continue
        if msg:
            head = f"%{msg.group('fac')}-{msg.group('sev')}-{msg.group('mn')}: {msg.group('msg')}"
            entries.append({"sev": int(msg.group("sev")), "key": f"%{msg.group('fac')}-{msg.group('sev')}-{msg.group('mn')}",
                            "head": head, "line": line, "ts": None if bogus else ts})
        else:
            entries.append({"sev": 2, "key": "(traceback)", "head": line.strip(), "line": line, "ts": None if bogus else ts})
    buf_size = None
    m = re.search(r"Log Buffer \((\d+) bytes\)", log_text)
    if m:
        buf_size = int(m.group(1))
    buffer_off = bool(re.search(r"Buffer logging:\s*disabled", log_text, re.I))
    if "Invalid input" in log_text or not log_text.strip():
        notes.append("'show logging' returned nothing usable on this switch.")
    if buffer_off:
        notes.append("Buffer logging is disabled on this switch, so there is no history to analyze ('logging buffered').")
    elif buf_size is not None and buf_size < 16384:
        notes.append(f"The log buffer is only {buf_size} bytes - older events may already be overwritten. "
                     "Consider 'logging buffered 65536' so more history is kept.")
    if entries and not ts_seen:
        notes.append("The log lines carry no timestamps (service timestamps log datetime), so times and the look-back window cannot be used.")
    elif ts_seen and star_seen > ts_seen // 2:
        notes.append("The switch clock was not synchronized (NTP) when most events were logged (lines start with *). The look-back window follows the "
                     "switch's own clock ('show clock'), so it still matches the log, but the dates may differ from real time.")
    if presync:
        notes.append(f"{presync} line(s) were logged before the switch clock was set (boot-time default date); they are treated as logged at the boot time.")
    if lookback_hours and not ts_seen and entries:
        notes.append("The look-back window was ignored because the log has no usable timestamps.")
    if outside:
        notes.append(f"{outside} older event(s) are outside the {lookback_hours}-hour look-back window and were left out "
                     f"(older than {cutoff.strftime('%b %d %H:%M:%S')} on the switch clock).")

    sev_counts = {str(i): 0 for i in range(8)}
    findings = {}
    others = {2: collections.Counter(), 3: collections.Counter()}
    key_counts = collections.Counter()
    key_example = {}
    flaps = collections.Counter()
    stp_changes = 0

    def add(fid, title, cat, lvl, advice, entry):
        f = findings.setdefault(fid, {"id": fid, "title": title, "category": cat, "level": lvl, "count": 0, "first": "", "last": "",
                                      "advice": advice, "examples": []})
        f["count"] += 1
        if entry is not None:
            t = entry["ts"].strftime("%b %d %H:%M:%S") if entry["ts"] else ""
            if t and not f["first"]:
                f["first"] = t
            if t:
                f["last"] = t
            ex = _diag_short(entry["head"])
            if ex not in f["examples"] and len(f["examples"]) < DIAG_MAX_EXAMPLES:
                f["examples"].append(ex)

    for e in entries:
        sev_counts[str(e["sev"])] += 1
        key_counts[e["key"]] += 1
        key_example.setdefault(e["key"], _diag_short(e["head"]))
        if e["key"] == "%LINK-3-UPDOWN":
            mm = re.search(r"Interface (\S+?),", e["head"])
            if mm:
                flaps[mm.group(1)] += 1
        if re.search(r"SPANTREE.{0,60}(TOPO|topology change)", e["head"], re.I):
            stp_changes += 1
        for rid, title, cat, lvl, rx, advice in _DIAG_RULES_C:
            if rx.search(e["head"]):
                add(rid, title, cat, lvl, advice, e)
                break
        else:
            if e["key"] in _LOG_NOISE_KEYS:
                continue
            if e["sev"] <= 2:
                others[2][e["key"]] += 1
            elif e["sev"] == 3:
                others[3][e["key"]] += 1
    flappers = [(i, n) for i, n in flaps.most_common() if n >= DIAG_FLAP_WARN]
    if flappers:
        f = {"id": "flap", "title": "Interface flapping", "category": "Interfaces", "level": "warn",
             "count": sum(n for _i, n in flappers), "first": "", "last": "",
             "advice": "Ports that keep going up and down are unstable (cable, SFP, or a looping / rebooting device). "
                       "Check them before the upgrade, or you will not know afterwards whether the upgrade caused it.",
             "examples": [f"{i}: {n} link state changes" for i, n in flappers[:DIAG_MAX_EXAMPLES]]}
        findings["flap"] = f
    if stp_changes >= DIAG_STP_WARN:
        findings["stp_storm"] = {"id": "stp_storm", "title": "Many spanning-tree topology changes", "category": "Interfaces",
                                 "level": "warn", "count": stp_changes, "first": "", "last": "",
                                 "advice": "Frequent topology changes mean an unstable layer-2 network; find the source (flapping port, loop) first.",
                                 "examples": []}
    for sev, lvl, title in ((2, "crit", "Other messages of severity 0-2 (emergency / alert / critical)"),
                            (3, "info", "Other error messages (severity 3)")):
        if others[sev]:
            findings[f"other{sev}"] = {
                "id": f"other{sev}", "title": title, "category": "Other", "level": lvl, "count": sum(others[sev].values()),
                "first": "", "last": "",
                "advice": "These do not match a known upgrade-relevant pattern. Read them and decide whether they matter.",
                "examples": [f"{k} x{n}" for k, n in others[sev].most_common(5)]}

    # ---- the other commands ----
    facts = {}
    clock_line, clock_src = _diag_clock_facts(clock_text)
    if clock_line:
        facts["clock"] = clock_line
    if clock_src:
        facts["time_source"] = clock_src
    if clock_line[:1] == "*":
        add("clock_unsync", "Switch clock is not synchronized", "System", "info",
            "'show clock' starts with * - the switch clock is not synchronized, so log times follow a clock that may differ from real time. "
            "Check 'show ntp status' and 'show ntp associations'.", None)
        findings["clock_unsync"]["examples"] = [clock_line]
    ver = re.search(r"(?im)\bVersion\s+([0-9][0-9A-Za-z.()\[\]-]*)", version_text)
    if ver:
        facts["version"] = ver.group(1).rstrip(",")
    up = re.search(r"(?im)\buptime is (.+)$", version_text)
    if up:
        facts["uptime"] = up.group(1).strip()
    rr = re.search(r"(?im)^Last reload reason\s*:?\s*(.+)$", version_text) or re.search(r"(?im)System returned to ROM by (.+)$", version_text)
    if rr:
        facts["reload_reason"] = rr.group(1).strip()
        if re.search(r"power|crash|exception|watchdog|abnormal|panic|kernel", rr.group(1), re.I):
            add("reload_reason", "Last reload was not a normal reload", "System", "warn",
                "The reason for the last reload looks abnormal. Find out why before adding another reload.", None)
            findings["reload_reason"]["examples"] = [_diag_short(rr.group(0))]
    mins = _diag_uptime_minutes(version_text)
    if mins is not None and mins < 60:
        add("recent_boot", "Switch booted less than an hour ago", "System", "info",
            "A freshly booted switch may still be settling (routing, stack sync). Wait before upgrading.", None)
        findings["recent_boot"]["examples"] = [f"uptime {facts.get('uptime', '')}"]
    stack = parse_show_switch(sections.get("show switch", ""))
    if stack is not None:
        facts["stack"] = stack
        bad = [r for r in stack if r["state"].lower() != "ready"]
        if bad:
            add("stack_state", "Stack member not Ready", "Stack", "crit",
                "Every stack member must be Ready before an upgrade; a member that is not Ready can be left behind or fail to join.", None)
            findings["stack_state"]["count"] = len(bad)
            findings["stack_state"]["examples"] = [f"switch {r['switch']} ({r['role']}): {r['state']}" for r in bad[:5]]
    # ---- stack ports, stack power, devices that are not authenticated (802.1X / MAB) ----
    members = len(stack) if stack else 0
    sp = parse_stack_ports(sections.get("show switch stack-ports", ""))
    if sp:
        ordered = sorted(sp.items(), key=lambda kv: int(kv[0]))
        facts["stack_ports"] = [{"switch": k, "ports": v} for k, v in ordered]
        down_sp = [f"switch {k} port {i}: {x}" for k, v in ordered for i, x in enumerate(v, 1) if x.lower() == "down"]
        if down_sp and members > 1:
            add("stack_port_down", "Stack port down", "Stack", "warn",
                "A stack cable or port is down, so the stack has lost redundancy (or is running as a chain). Fix it before upgrading a stack.", None)
            findings["stack_port_down"]["count"] = len(down_sp)
            findings["stack_port_down"]["examples"] = down_sp[:5]
    pw = parse_stack_power(sections.get("show stack-power", ""))
    if pw:
        facts["stack_power"] = [{"name": nm, "mode": v["mode"], "topology": v["topology"], "total_w": v["total"],
                                 "switches": v["sw"], "supplies": v["ps"]} for nm, v in pw.items()]
    dot1x_unauth = []
    auth = parse_auth_sessions(sections.get("show authentication sessions", ""))
    if auth is not None:
        bad_auth = [x for x in auth if not x["ok"]]
        facts["dot1x"] = {"sessions": len(auth), "authenticated": len(auth) - len(bad_auth), "not_authenticated": len(bad_auth)}
        dot1x_unauth = [{k: x[k] for k in ("port", "mac", "method", "domain", "status")} for x in bad_auth[:DIAG_MAX_DOT1X]]
        if bad_auth:
            add("dot1x_unauth", f"{len(bad_auth)} device(s) not authenticated (802.1X / MAB)", "Access control", "info",
                "These clients are connected but have not passed authentication (failed, unauthorized or still running). "
                "Check them before the upgrade so you can tell afterwards whether the upgrade changed anything. The full list is below.", None)
            findings["dot1x_unauth"]["count"] = len(bad_auth)
            findings["dot1x_unauth"]["examples"] = [f"{x['port']}  {x['mac']}  {x['method']}  {x['status']}" for x in bad_auth[:DIAG_MAX_EXAMPLES]]
    ed_text = sections.get("show interfaces status err-disabled", "")
    if ed_text and "Invalid input" not in ed_text and not re.search(r"(?m)^\s*%", ed_text):
        n_ed = len([l for l in ed_text.splitlines() if re.match(r"^\s*[A-Za-z]{2,}\d\S*\s.*\berr-disabled\b", l, re.I)])
        facts["err_disabled"] = n_ed
        if n_ed:
            add("errdisabled_now", f"{n_ed} port(s) currently err-disabled", "Interfaces", "warn",
                "These ports are down right now. Know why, so you can tell afterwards whether the upgrade changed anything.", None)
            findings["errdisabled_now"]["count"] = n_ed
    if buffer_off:
        findings["buffer_off"] = {"id": "buffer_off", "title": "Buffer logging is disabled", "category": "System", "level": "warn",
                                  "count": 1, "first": "", "last": "", "advice": "There is no log history to check. Enable 'logging buffered' and re-run later.",
                                  "examples": []}

    flist = sorted(findings.values(), key=lambda f: (_LEVEL_ORDER[f["level"]], -f["count"]))
    crit = sum(1 for f in flist if f["level"] == "crit")
    warn = sum(1 for f in flist if f["level"] == "warn")
    if crit:
        verdict, text = "red", f"Review before upgrading: {crit} critical finding(s)" + (f" and {warn} warning(s)." if warn else ".")
    elif warn:
        verdict, text = "amber", f"{warn} warning(s) found - check them before the maintenance window."
    elif not entries and not stack and "version" not in facts:
        verdict, text = "amber", "Nothing could be analyzed - see the notes."
    else:
        verdict, text = "green", "No upgrade-impacting events found in the available log."
    times = [e["ts"] for e in entries if e["ts"]]
    return {
        "host": host, "label": label or host, "time": now_str(), "verdict": verdict, "verdict_text": text,
        "lookback_hours": int(lookback_hours or 0),
        "window": {"clock": clock_line, "source": clock_src, "now": now.strftime("%b %d %Y %H:%M:%S"),
                   "from": cutoff.strftime("%b %d %Y %H:%M:%S") if cutoff else "", "used_switch_clock": clock_ok},
        "buffer": {"lines": len(entries), "outside_window": outside, "buffer_bytes": buf_size,
                   "first": min(times).strftime("%b %d %H:%M:%S") if times else "",
                   "last": max(times).strftime("%b %d %H:%M:%S") if times else ""},
        "severity": sev_counts, "findings": flist,
        "top": [{"key": k, "count": n, "example": key_example.get(k, "")} for k, n in key_counts.most_common(8)],
        "facts": facts, "notes": notes, "dot1x_unauth": dot1x_unauth,
    }


def format_analysis_report(a, files=None):
    """The analysis as a readable text file for the Storage folder."""
    out = [f"Log analysis - {a['label']} ({a['host']})",
           f"Collected   : {a['time']}",
           f"Look-back   : {_report_lookback(a)}",
           f"Verdict     : {a['verdict'].upper()} - {a['verdict_text']}",
           "This verdict is advisory, produced by built-in rules. Read the evidence and decide yourself.", ""]
    b = a["buffer"]
    out.append(f"Log buffer  : {b['lines']} message line(s) analyzed" + (f", {b['first']} -> {b['last']}" if b["first"] else ""))
    if a["facts"]:
        out.append("Facts       : " + "; ".join(f"{k}={v}" for k, v in a["facts"].items() if k not in _DIAG_COMPLEX_FACTS))
        for r in a["facts"].get("stack", []):
            out.append(f"  stack member {r['switch']}: {r['role']}, {r['state']}")
        for r in a["facts"].get("stack_ports", []):
            out.append(f"  stack ports of member {r['switch']}: port 1 {r['ports'][0]}, port 2 {r['ports'][1]}")
        for r in a["facts"].get("stack_power", []):
            out.append(f"  stack power {r['name']}: mode {r['mode']}, topology {r['topology']}, {r['total_w']} W, "
                       f"{r['switches']} switch(es), {r['supplies']} PSU")
        d1 = a["facts"].get("dot1x")
        if d1:
            out.append(f"  802.1X / MAB: {d1['sessions']} session(s), {d1['authenticated']} authenticated, {d1['not_authenticated']} not authenticated")
    for n in a["notes"]:
        out.append(f"Note        : {n}")
    out += ["", "Severity counts: " + ", ".join(f"{SEV_NAMES[int(k)]}={v}" for k, v in a["severity"].items() if v), "",
            "FINDINGS" if a["findings"] else "No findings."]
    for f in a["findings"]:
        span = f" ({f['first']} -> {f['last']})" if f["first"] else ""
        out.append(f"[{_LEVEL_LABEL[f['level']]}] {f['title']} - {f['category']} - x{f['count']}{span}")
        out.append(f"    What to do: {f['advice']}")
        for ex in f["examples"]:
            out.append(f"    evidence: {ex}")
    if a.get("dot1x_unauth"):
        out += ["", "DEVICES NOT AUTHENTICATED (802.1X / MAB)", f"  {'Port':<14} {'MAC address':<16} {'Method':<8} {'Domain':<8} Status"]
        out += [f"  {x['port']:<14} {x['mac']:<16} {x['method']:<8} {x['domain']:<8} {x['status']}" for x in a["dot1x_unauth"]]
    if a["top"]:
        out += ["", "MOST FREQUENT MESSAGES"]
        out += [f"{t['count']:>6}  {t['key']}   {t['example']}" for t in a["top"]]
    if files:
        out += ["", "Raw command output: " + files]
    return "\n".join(out) + "\n"



# ---- Log-analysis reports for the ticked switches: Excel, PDF ----
DIAG_REPORT_FORMATS = {"xlsx": ("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "xlsx"),
                       "pdf": ("application/pdf", "pdf")}
_REPORT_FINDING_HEAD = ["Switch", "IP address", "Verdict", "Analyzed", "Look-back", "Level", "Category", "Finding", "Count",
                        "First seen", "Last seen", "What to do", "Evidence"]
_REPORT_SUMMARY_HEAD = ["Switch", "IP address", "Verdict", "Advice", "Analyzed", "Look-back", "Critical", "Warnings", "Info",
                        "Log lines", "Log from", "Log to", "Version", "Uptime", "Last reload", "Stack", "Err-disabled ports", "Stack ports", "Stack power", "802.1X not authenticated", "Notes",
                        "Raw output file", "Report file"]


def _report_lookback(a):
    if not a.get("lookback_hours"):
        return "whole log buffer"
    w = a.get("window") or {}
    return f"{a['lookback_hours']} hours" + (f" (switch clock {w['from']} to {w['now']})" if w.get("from") else "")


def _report_counts(a):
    c = collections.Counter(f["level"] for f in a["findings"])
    return c["crit"], c["warn"], c["info"]


def diag_summary_rows(analyses):
    rows = []
    for a in analyses:
        crit, warn, info = _report_counts(a)
        f = a.get("facts") or {}
        stack = "; ".join(f"switch {r['switch']} {r['role']} {r['state']}" for r in f.get("stack", []))
        sp_txt = "; ".join(f"switch {r['switch']}: {r['ports'][0]}/{r['ports'][1]}" for r in f.get("stack_ports", []))
        pw_txt = "; ".join(f"{r['name']} {r['topology']} ({r['switches']} sw, {r['supplies']} PSU)" for r in f.get("stack_power", []))
        d1 = f.get("dot1x")
        dx_txt = f"{d1['not_authenticated']} of {d1['sessions']}" if d1 else ""
        rows.append([a["label"], a["host"], a["verdict"].upper(), a["verdict_text"], a["time"], _report_lookback(a), crit, warn, info,
                     a["buffer"]["lines"], a["buffer"]["first"], a["buffer"]["last"], f.get("version", ""), f.get("uptime", ""),
                     f.get("reload_reason", ""), stack, f.get("err_disabled", ""), sp_txt, pw_txt, dx_txt, " | ".join(a.get("notes", [])),
                     (a.get("files") or {}).get("logs", ""), (a.get("files") or {}).get("report", "")])
    return rows


def _ai_line(ai):
    """One line that says where an AI second opinion came from."""
    return f"{ai.get('provider', '')}, {ai.get('model', '')} - {ai.get('time', '')}" + (
        " - identifiers masked" if ai.get("masked") else " - identifiers NOT masked")


def diag_finding_rows(analyses):
    rows = []
    for a in analyses:
        base = [a["label"], a["host"], a["verdict"].upper(), a["time"], _report_lookback(a)]
        if not a["findings"]:
            rows.append(base + ["-", "-", "No findings", 0, "", "", "", ""])
        for f in a["findings"]:
            rows.append(base + [_LEVEL_LABEL[f["level"]], f["category"], f["title"], f["count"], f["first"], f["last"], f["advice"],
                                "\n".join(f["examples"])])
        if a.get("ai"):                                            # the AI second opinion, when it was asked for
            rows.append(base + ["AI", "AI second opinion", _ai_line(a["ai"]), "", "", "", a["ai"].get("text", ""), ""])
    return rows


def build_diag_xlsx(analyses):
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Font, PatternFill
    from openpyxl.utils import get_column_letter
    wb = Workbook()
    head_fill, head_font = PatternFill("solid", fgColor="1F4E78"), Font(bold=True, color="FFFFFF")
    verdict_fill = {"GREEN": "C6EFCE", "AMBER": "FFEB9C", "RED": "FFC7CE"}
    level_fill = {"CRITICAL": "FFC7CE", "WARNING": "FFEB9C", "INFO": "DDEBF7", "AI": "E4DFEC"}

    def sheet(ws, head, rows, widths, verdict_col=None, level_col=None):
        ws.append(head)
        for c in ws[1]:
            c.fill, c.font, c.alignment = head_fill, head_font, Alignment(vertical="center", wrap_text=True)
        for r in rows:
            ws.append(list(r))
        for row in ws.iter_rows(min_row=2):
            for c in row:
                c.alignment = Alignment(vertical="top", wrap_text=True)
                if isinstance(c.value, str) and c.value.startswith("="):
                    c.data_type = "s"                      # keep text that starts with = as text, never as a formula
            if verdict_col is not None and row[verdict_col].value in verdict_fill:
                row[verdict_col].fill = PatternFill("solid", fgColor=verdict_fill[row[verdict_col].value])
            if level_col is not None and row[level_col].value in level_fill:
                row[level_col].fill = PatternFill("solid", fgColor=level_fill[row[level_col].value])
        for i, wdt in enumerate(widths, 1):
            ws.column_dimensions[get_column_letter(i)].width = wdt
        ws.freeze_panes = "A2"
        ws.auto_filter.ref = ws.dimensions

    ws = wb.active
    ws.title = "Summary"
    sheet(ws, _REPORT_SUMMARY_HEAD, diag_summary_rows(analyses),
          [22, 16, 10, 46, 19, 16, 9, 9, 7, 10, 16, 16, 14, 28, 26, 34, 12, 26, 34, 14, 50, 34, 34], verdict_col=2)
    sheet(wb.create_sheet("Findings"), _REPORT_FINDING_HEAD, diag_finding_rows(analyses),
          [22, 16, 10, 19, 16, 10, 12, 38, 8, 16, 16, 60, 70], verdict_col=2, level_col=5)
    top = []
    for a in analyses:
        for t in a.get("top", []):
            top.append([a["label"], a["host"], t["count"], t["key"], t["example"]])
    sheet(wb.create_sheet("Top messages"), ["Switch", "IP address", "Count", "Message ID", "Example"], top, [22, 16, 8, 30, 110])
    ai_rows = [[a["label"], a["host"], a["ai"].get("provider", ""), a["ai"].get("model", ""), a["ai"].get("time", ""),
                "Yes" if a["ai"].get("masked") else "No", a["ai"].get("text", "")] for a in analyses if a.get("ai")]
    if ai_rows:
        sheet(wb.create_sheet("AI analysis"), ["Switch", "IP address", "Provider", "Model", "Time", "Identifiers masked", "AI analysis"],
              ai_rows, [22, 16, 22, 24, 19, 12, 120])
    unauth = [[a["label"], a["host"], x["port"], x["mac"], x["method"], x["domain"], x["status"]]
              for a in analyses for x in a.get("dot1x_unauth", [])]
    if unauth:
        sheet(wb.create_sheet("Not authenticated"), ["Switch", "IP address", "Port", "MAC address", "Method", "Domain", "Status"],
              unauth, [22, 16, 16, 18, 10, 10, 20])
    out = io.BytesIO()
    wb.save(out)
    return out.getvalue()


# --- a tiny PDF writer (text + coloured boxes), so no extra library is needed ---
_HELV = [278, 278, 355, 556, 556, 889, 667, 191, 333, 333, 389, 584, 278, 333, 278, 278] + [556] * 10 + [278, 278, 584, 584, 584, 556, 1015,
        667, 667, 722, 722, 667, 611, 778, 722, 278, 500, 667, 556, 833, 722, 778, 667, 778, 722, 667, 611, 722, 667, 944, 667, 667, 611,
        278, 278, 278, 469, 556, 333, 556, 556, 500, 556, 556, 278, 556, 556, 222, 222, 500, 222, 833, 556, 556, 556, 556, 333, 500, 278,
        556, 500, 722, 500, 500, 500, 334, 260, 334, 584]


def _pdf_width(text, size, font):
    if font == "F3":
        return len(text) * size * 0.6
    w = sum(_HELV[ord(c) - 32] if 32 <= ord(c) < 127 else 556 for c in text) * size / 1000.0
    return w * (1.06 if font == "F2" else 1.0)


def _pdf_wrap(text, width, size, font):
    lines = []
    for para in str(text).split("\n"):
        words, cur = para.split(" "), ""
        for w in words:
            while font == "F3" and _pdf_width(w, size, font) > width:       # a long unbroken token (monospace evidence)
                k = max(1, int(width // (size * 0.6)))
                if cur:
                    lines.append(cur)
                    cur = ""
                lines.append(w[:k])
                w = w[k:]
            trial = (cur + " " + w) if cur else w
            if cur and _pdf_width(trial, size, font) > width:
                lines.append(cur)
                cur = w
            else:
                cur = trial
        lines.append(cur)
    return lines


class _MiniPdf:
    W, H, M = 595.0, 842.0, 40.0

    def __init__(self, title, landscape=False):
        self.title, self.pages, self.cur, self.y = title, [], None, 0.0
        if landscape:
            self.W, self.H = 842.0, 595.0
        self._new_page()

    def _new_page(self):
        self.cur = []
        self.pages.append(self.cur)
        self.y = self.H - self.M

    def _need(self, h):
        if self.y - h < self.M + 14:
            self._new_page()

    @staticmethod
    def _enc(t):
        return t.encode("cp1252", "replace").decode("latin-1").replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")

    def rect(self, x, y, w, h, rgb):
        self.cur.append(f"{rgb[0]:.3f} {rgb[1]:.3f} {rgb[2]:.3f} rg {x:.1f} {y:.1f} {w:.1f} {h:.1f} re f")

    def line(self, text, font="F1", size=9.5, indent=0.0, rgb=(0, 0, 0), after=2.0, bg=None):
        width = self.W - 2 * self.M - indent
        for ln in _pdf_wrap(text, width, size, font):
            lh = size * 1.28
            self._need(lh)
            if bg:
                self.rect(self.M + indent - 3, self.y - lh + 2, width + 6, lh, bg)
            self.cur.append(f"BT /{font} {size:.1f} Tf {rgb[0]:.3f} {rgb[1]:.3f} {rgb[2]:.3f} rg {self.M + indent:.1f} {self.y - size:.1f} Td ({self._enc(ln)}) Tj ET")
            self.y -= lh
        self.y -= after

    def gap(self, h):
        self.y -= h

    def table(self, cols, rows, size=8.0):
        """A table with any number of columns and rows: widths follow the content, long cells wrap, the header repeats on every page."""
        total, n, lh = self.W - 2 * self.M, max(1, len(cols)), size * 1.25
        lens = []
        for i, c in enumerate(cols):
            m = max([len(str(c))] + [len(str(r[i])) for r in rows[:300] if i < len(r)])
            lens.append(max(6, min(m, 45)))
        widths = [total * ln / float(sum(lens)) for ln in lens]

        def lines_of(txt, w, font):
            maxc = max(4, int((w - 6) / (size * 0.5)))
            txt = re.sub(r"(\S{%d})(?=\S)" % maxc, r"\1 ", str(txt))
            ls = _pdf_wrap(txt, w - 6, size, font) or [""]
            if len(ls) > 14:
                ls = ls[:14]
                ls[-1] = ls[-1][:max(0, len(ls[-1]) - 3)] + "..."
            return ls

        def measure(cells, font):
            wrapped = [lines_of(c, w, font) for c, w in zip(cells, widths)]
            return wrapped, max(len(x) for x in wrapped) * lh + 5

        def put(wrapped, h, font, bg):
            if bg:
                self.rect(self.M, self.y - h, total, h, bg)
            x = self.M
            for ls, w in zip(wrapped, widths):
                for k, ln in enumerate(ls):
                    self.cur.append(f"BT /{font} {size:.1f} Tf 0 0 0 rg {x + 3:.1f} {self.y - 3 - size - k * lh:.1f} Td ({self._enc(ln)}) Tj ET")
                x += w
            self.y -= h

        hw, hh = measure(list(cols), "F2")
        self._need(hh + 24)
        put(hw, hh, "F2", (0.85, 0.89, 0.95))
        for ri, r in enumerate(rows):
            r = list(r)[:n] + [""] * (n - len(r))
            wr, h = measure(r, "F1")
            pg = len(self.pages)
            self._need(h)
            if len(self.pages) != pg:
                put(hw, hh, "F2", (0.85, 0.89, 0.95))
            put(wr, h, "F1", (0.96, 0.96, 0.96) if ri % 2 else None)

    def bar(self, text, rgb, fg=(0, 0, 0)):
        self._need(20)
        self.rect(self.M, self.y - 17, self.W - 2 * self.M, 18, rgb)
        self.cur.append(f"BT /F2 11 Tf {fg[0]:.3f} {fg[1]:.3f} {fg[2]:.3f} rg {self.M + 6:.1f} {self.y - 13:.1f} Td ({self._enc(text[:95])}) Tj ET")
        self.y -= 24

    def build(self):
        import zlib
        n = len(self.pages)
        objs = [None] * (4 + n * 2 + 1)                      # 1 catalog, 2 pages, 3.. fonts, then page + stream pairs
        objs[0] = b"<< /Type /Catalog /Pages 2 0 R >>"
        kids = " ".join(f"{5 + i * 2} 0 R" for i in range(n))
        objs[1] = f"<< /Type /Pages /Kids [{kids}] /Count {n} >>".encode()
        objs[2] = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
        objs[3] = b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
        courier = b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>"
        for i, ops in enumerate(self.pages):
            foot = f"BT /F1 8 Tf 0.4 0.4 0.4 rg {self.M:.1f} 22 Td ({self._enc(self.title)}) Tj ET BT /F1 8 Tf 0.4 0.4 0.4 rg {self.W - self.M - 50:.1f} 22 Td (Page {i + 1} of {n}) Tj ET"
            data = zlib.compress(("\n".join(ops) + "\n" + foot).encode("latin-1"))
            objs[4 + i * 2 + 1] = b"<< /Filter /FlateDecode /Length %d >>\nstream\n" % len(data) + data + b"\nendstream"
            objs[4 + i * 2] = (f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {self.W:.0f} {self.H:.0f}] /Contents {6 + i * 2} 0 R "
                               f"/Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 {5 + n * 2} 0 R >> >> >>").encode()
        objs[4 + n * 2] = courier
        out, offs = bytearray(b"%PDF-1.4\n"), []
        for i, o in enumerate(objs):
            offs.append(len(out))
            out += f"{i + 1} 0 obj\n".encode() + o + b"\nendobj\n"
        xref = len(out)
        out += f"xref\n0 {len(objs) + 1}\n0000000000 65535 f \n".encode()
        for o in offs:
            out += f"{o:010d} 00000 n \n".encode()
        out += f"trailer\n<< /Size {len(objs) + 1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode()
        return bytes(out)


def build_diag_pdf(analyses, site=""):
    title = "Log analysis report" + (f" - {site}" if site else "")
    pdf = _MiniPdf(title)
    pdf.line(title, "F2", 17, after=4)
    pdf.line(f"Generated {now_str()}  |  {len(analyses)} switch(es)  |  advisory results of built-in rules - read the evidence and decide yourself.",
             "F1", 9, rgb=(0.35, 0.35, 0.35), after=8)
    colors = {"green": (0.78, 0.94, 0.81), "amber": (1.0, 0.92, 0.61), "red": (1.0, 0.78, 0.81)}
    pdf.line("Summary", "F2", 12, after=3)
    for a in analyses:
        crit, warn, info = _report_counts(a)
        pdf.line(f"{a['verdict'].upper():<6} {a['label']} ({a['host']})  -  critical {crit}, warnings {warn}, info {info}",
                 "F1", 9.5, bg=colors[a["verdict"]], after=1.5)
    pdf.gap(8)
    for a in analyses:
        pdf._need(70)
        pdf.bar(f"{a['label']}  ({a['host']})  -  {a['verdict'].upper()}", colors[a["verdict"]])
        pdf.line(a["verdict_text"], "F2", 10, after=2)
        b = a["buffer"]
        pdf.line(f"Analyzed {a['time']}  |  {_report_lookback(a)}  |  {b['lines']} log message(s)" + (f", {b['first']} to {b['last']}" if b["first"] else ""),
                 "F1", 8.5, rgb=(0.35, 0.35, 0.35), after=1)
        f = a.get("facts") or {}
        facts = [f"version {f['version']}" if f.get("version") else "", f"uptime {f['uptime']}" if f.get("uptime") else "",
                 f"last reload: {f['reload_reason']}" if f.get("reload_reason") else "",
                 ("stack: " + ", ".join(f"{r['switch']} {r['state']}" for r in f["stack"])) if f.get("stack") else "",
                 f"{f['err_disabled']} err-disabled port(s)" if isinstance(f.get("err_disabled"), int) else "",
                 ("stack ports: " + ", ".join(f"{r['switch']}:{r['ports'][0]}/{r['ports'][1]}" for r in f["stack_ports"])) if f.get("stack_ports") else "",
                 ("stack power: " + ", ".join(f"{r['name']} {r['topology']}" for r in f["stack_power"])) if f.get("stack_power") else "",
                 (f"802.1X: {f['dot1x']['not_authenticated']} of {f['dot1x']['sessions']} not authenticated") if f.get("dot1x") else ""]
        facts = [x for x in facts if x]
        if facts:
            pdf.line(" | ".join(facts), "F1", 8.5, rgb=(0.35, 0.35, 0.35), after=1)
        for n in a.get("notes", []):
            pdf.line("Note: " + n, "F1", 8.5, rgb=(0.35, 0.35, 0.35), after=1)
        pdf.gap(3)
        if not a["findings"]:
            pdf.line("No findings.", "F1", 9.5, after=6)
        for fd in a["findings"]:
            span = f"  {fd['first']} to {fd['last']}" if fd["first"] and fd["last"] != fd["first"] else (f"  {fd['first']}" if fd["first"] else "")
            col = {"crit": (0.78, 0.16, 0.23), "warn": (0.6, 0.4, 0.0), "info": (0.04, 0.42, 0.66)}[fd["level"]]
            pdf.line(f"[{_LEVEL_LABEL[fd['level']]}] {fd['title']}  ({fd['category']}, {fd['count']}x{span})", "F2", 9.5, rgb=col, after=1)
            pdf.line("What to do: " + fd["advice"], "F1", 9, indent=10, after=1)
            for ex in fd["examples"]:
                pdf.line(ex, "F3", 7.5, indent=10, rgb=(0.25, 0.25, 0.25), after=0.5)
            pdf.gap(4)
        if a.get("ai"):
            pdf._need(40)
            pdf.line("AI analysis (advisory - check it against the evidence above)", "F2", 10, rgb=(0.27, 0.2, 0.55), after=1)
            pdf.line(_ai_line(a["ai"]), "F1", 8.5, indent=10, rgb=(0.35, 0.35, 0.35), after=2)
            pdf.line(a["ai"].get("text", ""), "F1", 9, indent=10, after=4)
        pdf.gap(8)
    return pdf.build()


def build_diag_report(fmt, analyses, site=""):
    if fmt == "xlsx":
        return build_diag_xlsx(analyses)
    if fmt == "pdf":
        return build_diag_pdf(analyses, site)
    raise ValueError("format")


# ---- Command time test report (Troubleshoot tab): Excel and PDF ----
def _ct_text(v, n=300):
    return "" if v is None else str(v)[:n]


def _ct_num(v):
    return round(float(v), 2) if isinstance(v, (int, float)) and not isinstance(v, bool) else ""


def _ct_clean(r):
    """Keep only what the report prints, with sane sizes (the page sends its measured values)."""
    r = r if isinstance(r, dict) else {}
    h = r.get("host") if isinstance(r.get("host"), dict) else {}
    cmds = [c for c in (r.get("cmds") or []) if isinstance(c, dict)][:200]
    details = [d for d in (r.get("details") or []) if isinstance(d, dict)][:50]
    rows = [x for x in (r.get("rows") or []) if isinstance(x, dict)][:100]
    return {
        "host": {k: _ct_text(h.get(k), 120) for k in ("host", "label", "platform", "version")},
        "image": _ct_text(r.get("image"), 200), "when": _ct_text(r.get("when"), 60), "site": _ct_text(r.get("site"), 80),
        "ver": _ct_text(r.get("ver"), 40), "margin": _ct_num(r.get("margin")), "keep_default": bool(r.get("keep_default")),
        "cmds": [{"group": _ct_text(c.get("group"), 80), "command": _ct_text(c.get("command")), "feeds": _ct_text(c.get("feeds"), 120),
                  "n": _ct_num(c.get("n")), "last": _ct_num(c.get("last")), "max": _ct_num(c.get("max")), "avg": _ct_num(c.get("avg")),
                  "status": _ct_text(c.get("status"), 60)} for c in cmds],
        "details": [{"name": _ct_text(d.get("name"), 120),
                     "parts": [{"command": _ct_text(p.get("command")), "n": _ct_num(p.get("n")), "lastS": _ct_num(p.get("lastS")),
                                "max": _ct_num(p.get("max")), "avg": _ct_num(p.get("avg"))}
                               for p in (d.get("parts") or []) if isinstance(p, dict)][:100]} for d in details],
        "rows": [{"label": _ct_text(x.get("label"), 120), "key": _ct_text(x.get("key"), 80), "measured": _ct_num(x.get("measured")),
                  "def": _ct_num(x.get("def")), "value": _ct_num(x.get("value"))} for x in rows],
    }


def build_ct_xlsx(r):
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Font, PatternFill
    from openpyxl.utils import get_column_letter
    r = _ct_clean(r)
    wb = Workbook()
    head_fill, head_font = PatternFill("solid", fgColor="1F4E78"), Font(bold=True, color="FFFFFF")

    def sheet(ws, head, rows, widths):
        ws.append(head)
        for c in ws[1]:
            c.fill, c.font, c.alignment = head_fill, head_font, Alignment(vertical="center", wrap_text=True)
        for row in rows:
            ws.append(list(row))
        for row in ws.iter_rows(min_row=2):
            for c in row:
                c.alignment = Alignment(vertical="top", wrap_text=True)
                if isinstance(c.value, str) and c.value.startswith("="):
                    c.data_type = "s"
        for i, w in enumerate(widths, 1):
            ws.column_dimensions[get_column_letter(i)].width = w
        ws.freeze_panes = "A2"

    h = r["host"]
    sheet(wb.active, ["Item", "Value"], [
        ["Report", "Command time test"], ["Generated", r["when"]], ["Application", f"{APP_NAME} {r['ver']}".strip()], ["Site", r["site"]],
        ["Switch address", h["host"]], ["Switch name", h["label"]], ["Platform", h["platform"]], ["Software version", h["version"]],
        ["Image tested with", r["image"]], ["Safety margin (x)", r["margin"]],
        ["Never below the default", "yes" if r["keep_default"] else "no"]], [28, 60])
    wb.active.title = "Summary"
    sheet(wb.create_sheet("Step times"), ["Stage", "Step", "Feeds this timeout", "Runs", "Last (s)", "Slowest (s)", "Average (s)", "Last result"],
          [[c["group"], c["command"], c["feeds"], c["n"], c["last"], c["max"], c["avg"], c["status"]] for c in r["cmds"]],
          [22, 54, 30, 7, 10, 12, 12, 16])
    det = [[d["name"], p["command"], p["n"], p["lastS"], p["max"], p["avg"]] for d in r["details"] for p in d["parts"]]
    if det:
        sheet(wb.create_sheet("Step detail"), ["Step", "Measured", "Runs", "Last (s)", "Slowest (s)", "Average (s)"], det, [34, 54, 7, 10, 12, 12])
    sheet(wb.create_sheet("Suggested timeouts"), ["Timeout setting", "Setting key", "Slowest measured (s)", "Default (s)", "Suggested (s)"],
          [[x["label"], x["key"], x["measured"], x["def"], x["value"]] for x in r["rows"]], [40, 30, 20, 14, 14])
    buf = io.BytesIO()
    wb.save(buf)
    return buf.getvalue()


def build_ct_pdf(r):
    r = _ct_clean(r)
    h = r["host"]
    pdf = _MiniPdf(f"{APP_NAME} - Command Time Test", landscape=True)
    pdf.line("Command Time Test Report", "F2", 17, after=4)
    pdf.line(f"{r['when']}  |  {APP_NAME} {r['ver']}".rstrip() + (f"  |  Site: {r['site']}" if r["site"] else ""), "F1", 9, rgb=(0.35, 0.35, 0.35), after=8)
    pdf.line("Switch", "F2", 12, after=3)
    pdf.table(["Address", "Name", "Platform", "Software version", "Image tested with"],
              [[h["host"], h["label"], h["platform"], h["version"], r["image"]]], 8.5)
    pdf.gap(10)
    pdf.line("Measured Step Times", "F2", 12, after=3)
    f = lambda v: "-" if v == "" else v
    pdf.table(["Stage", "Step", "Feeds this timeout", "Runs", "Last (s)", "Slowest (s)", "Average (s)", "Last result"],
              [[c["group"], c["command"], c["feeds"], f(c["n"]), f(c["last"]), f(c["max"]), f(c["avg"]), c["status"]] for c in r["cmds"]], 8)
    for d in r["details"]:
        pdf.gap(10)
        pdf.line(f"{d['name']} - detail", "F2", 11, after=3)
        pdf.table(["Measured", "Runs", "Last (s)", "Slowest (s)", "Average (s)"],
                  [[p["command"], f(p["n"]), f(p["lastS"]), f(p["max"]), f(p["avg"])] for p in d["parts"]], 8)
    pdf.gap(10)
    pdf.line("Suggested Timeouts", "F2", 12, after=2)
    pdf.line(f"Slowest measured time x {r['margin']}, rounded up to 5 seconds" + (", never below the default" if r["keep_default"] else "") +
             ". 'Whole install' is the add step plus the activation.", "F1", 8.5, rgb=(0.35, 0.35, 0.35), after=3)
    pdf.table(["Timeout setting", "Slowest measured (s)", "Default (s)", "Suggested (s)"],
              [[x["label"], f(x["measured"]), f(x["def"]), f(x["value"])] for x in r["rows"]], 8)
    return pdf.build()


